---@class SResourcesMgr
local SResourcesMgr = T(Global, "SResourcesMgr")
---@type SResources
local Resources = Plugins.Require("resources", "server.data.SResources")
---@type PidPacketSender : SPidPacketSender
local PidPacketSender = T(Global, "PidPacketSender")
---@type PathUtil
local PathUtil = T(Global, "PathUtil")
-- 引入lfs模块用于文件系统操作
local lfs = require("lfs")
---@type [string, SResources]
local AllResources = {}
local index = 1

-- 商店数据文件路径
local RESOURCES_DATA_PATH = "plugins/resources/resources.json"

-- 保存商店数据到JSON文件
function SResourcesMgr:saveResourcesToFile()
    local resourcesData = {
        resources = {},
        index = index
    }
    
    -- 收集所有商店的保存信息
    for id, resources in pairs(AllResources) do
        local saveInfo = resources:getSaveInfo()
        if saveInfo.info.item and saveInfo.info.item[1] ~= 0 then
            resourcesData.resources[id] = saveInfo
        end
    end
    
    -- 构建完整的文件路径
    local fullPath = FileUtil:getMapPath() .. RESOURCES_DATA_PATH
    
    -- 检测并创建目录
    local dirPath = FileUtil:getMapPath() .. "plugins/resources/"
    
    -- 检查目录是否存在，不存在则创建
    local attr = lfs.attributes(dirPath)
    if not attr then
        -- 逐级创建目录
        local pluginsDir = FileUtil:getMapPath() .. "plugins/"
        local pluginsAttr = lfs.attributes(pluginsDir)
        if not pluginsAttr then
            local success, err = lfs.mkdir(pluginsDir)
            if not success then
                print("failed to create plugins directory: " .. (err or "unknown error"))
                return
            end
        end
        
        local success, err = lfs.mkdir(dirPath)
        if not success then
            print("failed to create resources directory: " .. (err or "unknown error"))
            return
        end
        print("created directory: " .. dirPath)
    end
    
    -- 转换为JSON字符串
    local jsonData = json.encode(resourcesData)
    
    -- 尝试写入文件 (使用io.open方式，如果支持的话)
    local file = io.open(fullPath, "w")
    if file then
        file:write(jsonData)
        file:close()
        print("save resources to file: " .. fullPath)
    else
        print("failed to create resources file: " .. fullPath)
    end
end

-- 从JSON文件加载商店数据
function SResourcesMgr:loadResourcesFromFile()
    local fullPath = FileUtil:getMapPath() .. RESOURCES_DATA_PATH
    
    -- 检查文件是否存在
    if not PathUtil:isFileExist(fullPath) then
        print("resources file not exist: " .. fullPath)
        return
    end
    
    -- 尝试读取文件
    local file = io.open(fullPath, "r")
    if not file then
        print("failed to read resources file: " .. fullPath)
        return
    end
    
    local jsonData = file:read("*all")
    file:close()
    
    if not jsonData or jsonData == "" then
        print("resources file is empty")
        return
    end
    
    -- 解析JSON数据
    local success, resourcesData = pcall(json.decode, jsonData)
    if not success or not resourcesData then
        print("resources file format error")
        return
    end
    
    -- 清空现有商店数据
    AllResources = {}
    
    -- 恢复index
    if resourcesData.index then
        index = resourcesData.index
    end
    
    -- 恢复商店数据
    if resourcesData.resources then
        for id, saveInfo in pairs(resourcesData.resources) do
            local resources = Resources.new(id, saveInfo)
            if resources then
                AllResources[id] = resources
            end
        end
    end
    
    local resourcesCount = TableUtil.getTableSize(AllResources)
    print("load " .. resourcesCount .. " resources from file")
    
    -- 同步到所有客户端
    if resourcesCount > 0 then
        local syncData = {}
        for id, resources in pairs(AllResources) do
            syncData[id] = resources:getSyncInfo()
        end
        PacketSender:broadCastPidPacket({
            pid = "syncResources",
            data = syncData
        })
        print("sync resources to all clients")
    end
end

-- 初始化商店管理器
function SResourcesMgr:init()
    self:loadResourcesFromFile()
    CEvents.PlayerPickupItemEndEvent:registerCallBack(function(rakssid, itemId, itemNum, _, entityId)
        local player = PlayerManager:getPlayerByRakssid(rakssid)
        if not player then
            return
        end
        self:onItemPickUp(entityId)
    end)
end

function SResourcesMgr:addResources(data)
    local syncData = {}
    for _, info in pairs(data) do
        if TableUtil.getTableSize(AllResources) >= Define.ResourceMax then
            return
        end
        local resources = Resources.new(index, info)
        if resources then
            AllResources[tostring(index)] = resources
            syncData[tostring(index)] = resources:getSyncInfo()
            index = index + 1
        end
    end
    PacketSender:broadCastPidPacket({
        pid = "syncResources",
        data = syncData
    })
    -- 保存到文件
    self:saveResourcesToFile()
end

function SResourcesMgr:createNewResources(userId, pos)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    if TableUtil.getTableSize(AllResources) >= Define.ResourceMax then
        PidPacketSender:sendShopTip(player.userId, "gui.resources.max")
        return false
    end
    local syncData = {}
    local resourcesId = tostring(index)
    local resources = Resources.new(resourcesId, {
        info = {
            item = { 0, 0 },
            interval = Define.IntervalMin,
            max = Define.MaxItemMin
        },
        pos = pos
    })
    if resources then
        AllResources[resourcesId] = resources
        syncData[resourcesId] = resources:getSyncInfo()
        PacketSender:sendPidPacket(player.rakssid, {
            pid = "syncResources",
            data = syncData,
            showId = resourcesId
        })
        index = index + 1
        -- 保存到文件
        self:saveResourcesToFile()
        return resourcesId
    end
    return false
end

function SResourcesMgr:removeResources(id)
    local resources = AllResources[tostring(id)]
    if not resources then
        return
    end
    resources:onRemove()
    AllResources[tostring(id)] = nil
    PacketSender:broadCastPidPacket({
        pid = "removeResources",
        id = id
    })
    -- 保存到文件
    self:saveResourcesToFile()
end

function SResourcesMgr:syncResources(userId)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local data = {}
    for id, resources in pairs(AllResources) do
        data[id] = resources:getSyncInfo()
    end
    player:sendPacket({
        pid = "syncResources",
        data = data
    })
end

---@return SResources
function SResourcesMgr:getResources(id)
    return AllResources[tostring(id)]
end

function SResourcesMgr:tryPlaceResources(userId, pos)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(userId) then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.no.permission")
        return
    end
    if player:haveItemCount(Define.ResourceItemId) <= 0 then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.no.enough.item")
        return
    end
    if TableUtil.getTableSize(AllResources) >= Define.ResourceMax then
        PidPacketSender:sendShopTip(player.userId, "gui.resource.max")
        return
    end
    local resourcesId = self:createNewResources(userId, pos)
    if resourcesId then
        player:removeItem(Define.ResourceItemId, 1)
    end
end

function SResourcesMgr:onTick(ticks)
    for _, resource in pairs(AllResources) do
        resource:onTick(ticks)
    end
end

function SResourcesMgr:onItemPickUp(entityId)
    for _, resource in pairs(AllResources) do
        resource:onItemPickUp(entityId)
    end
end

function SResourcesMgr:canPlaceBlock(blockPos)
    for _, resource in pairs(AllResources) do
        if not resource:canPlaceBlock(blockPos) then
            return false
        end
    end
    return true
end

function SResourcesMgr:resetResources()
    for _, resource in pairs(AllResources) do
        resource:reset()
    end
end

SResourcesMgr:init()
return SResourcesMgr